on_complete = {
		county.holder = {
			if = { # MDE Modified
				limit = {
					OR = {
						mde_never_map_egg_spawn_trigger = yes
						has_global_variable = summerhall_egg_found
					}
				}
			}
			else_if = {
				limit = {
					mde_guaranteed_map_egg_spawn_trigger = yes
				}
				trigger_event = agot_ruins.2000
			}
			else = {
				random_list = {
					1 = {
						modifier = {
							factor = mde_egg_map_spawn_factor
						}
						trigger_event = agot_ruins.2000
					}
					3 = {} #Nothing happens
				}
			}
		}
	}

