		hidden_effect = {
			if = {
				limit = {
					county.holder = { is_human = yes }
				}
				county.holder = {
					random_list = {
						1 = { trigger_event = agot_colonization_events.1201 }
						1 = { trigger_event = agot_colonization_events.1202 }
						1 = { trigger_event = agot_colonization_events.1203 }
						1 = { trigger_event = agot_colonization_events.1204 }
						1 = { trigger_event = agot_colonization_events.1205 }
						1 = { trigger_event = agot_colonization_events.1206 }
						6 = { root = { remove_building = bandits_cleared } }
					}
				}
			}
			else = {
				set_variable = bandits
				trigger_event = agot_colonization_events.9001
			}
		}
		cleanup_cleared_blockers_effect = yes
	}

