		trigger_if = {
			limit = {
				culture = { has_cultural_parameter = second_caravanserai }
			}
			custom_tooltip = {
				text = has_two_caravanserai_in_county
				county = {
					any_county_province = {
						count < 2
						has_building_or_higher = caravanserai_01
					}
				}
			}
		}
		trigger_else = {
			custom_tooltip = {
				text = not_allowed_second_caravanserai
				county = {
					any_county_province = {
						count < 1
						has_building_or_higher = caravanserai_01
					}
				}
			}
		}
	}

