on_complete.script:
on_complete = {
		save_scope_as = obstacle_province
		hidden_effect = {
			if = {
				limit = {
					county.holder = { is_human = yes }
				}
				county.holder = {
					random_list = {
						1 = { trigger_event = agot_colonization_events.1401 }
						1 = { trigger_event = agot_colonization_events.1402 }
						2 = { root = { remove_building = flooded_lands_cleared } }
					}
				}
			}
			else = {
				set_variable = flooded_lands
				trigger_event = agot_colonization_events.9001
			}
		}
		cleanup_cleared_blockers_effect = yes
	}

