on_complete = {
		save_scope_as = obstacle_province
		county = { save_scope_as = obstacle_county }
		hidden_effect = {
			if = {
				limit = {
					county.holder = { is_human = yes }
				}
				county.holder = {
					random_list = {
						1 = { trigger_event = agot_colonization_events.1501 }
						1 = { trigger_event = agot_colonization_events.1502 }
						1 = { trigger_event = agot_colonization_events.1503 }
						1 = { trigger_event = agot_colonization_events.1504 }
						4 = {
							trigger_event = {
								id = agot_colonization_events.1590
								days = 1
							}
						}
						8 = {
							trigger = {
								is_ai = yes
							}
							make_settlement_county_wilderness = { COUNTY = scope:obstacle_county }
							trigger_event = {
								id = agot_colonization_events.1580
								delayed = yes
							}
						}
					}
				}
			}
			else = {
				set_variable = pirate_remnants
				trigger_event = agot_colonization_events.9001
			}
		}
		cleanup_cleared_blockers_effect = yes
	}

