		custom_tooltip = {
			text = only_single_great_project_type_allowed
			NOT = { any_great_project = { great_project_type = agot_special_building_numdym } }
		}
		title:b_chroyane.title_province = { has_building = agot_ruins_chroyane_walls_04 }
		title:b_the_sorrows.title_province = { has_building = agot_ruins_palace_of_sorrows_05 }
		title:b_tul_poy.title_province = { has_building = agot_ruins_temple_of_the_womb_03 }
		title:b_shroudfall.title_province = { has_building = agot_ruins_fogs_touch_quarter_03 }
		title:b_the_visage.title_province = { has_building = agot_ruins_festival_calle_03 }
		title:b_denllal.title_province = { has_building = agot_ruins_bridge_of_dreams_03 }
		title:b_romsas.title_province = { has_building = agot_ruins_home_port_03 }
		title:b_asolheam.title_province = { has_building = agot_ruins_foreign_port_03 }
	}

