	on_plan_build = {
		agot_chroyane_building_gp_owner_planning_memory_effect = { PROVINCE = title:b_numdym }
	}

	on_start_build = {
		scope:owner = {
			if = {
				limit = { has_legitimacy = yes }
				add_legitimacy_effect = { LEGITIMACY = minor_legitimacy_gain }
			}
		}
		scope:great_project = {
			every_contribution = {
				limit = { contribution_is_funded = yes }
				contributor = { add_prestige = minor_prestige_value }
			}
		}
	}

	on_invalidated = {}

	on_complete = {
		if = {
			limit = { NOT = { has_global_variable = numdym_building_upgrade_completed } }
			set_global_variable = numdym_building_upgrade_completed
		}
		if = {
			limit = { title:b_numdym.title_province = { NOT = { has_holding_type = city_holding } } }
