	}

	name = {
		desc = great_project_type_construct_great_fleet_01
	}

	is_important = yes

	is_shown = {
		is_landed = yes
		is_lowborn = no
		NOR = {
			is_planning_great_project = construct_great_fleet_01
			government_has_flag = government_is_tribal
			government_has_flag = government_is_nw
			any_held_county = {
				any_county_province = {
					has_building_or_higher = agot_great_fleet_01
				}
			}
		}
	}

	can_start_planning = {
		trigger_if = {
			limit = {
				agot_is_independent_ruler = no
			}
			trigger_if = {
				limit = {
					exists = var:agot_pwl_top
				}
				has_strong_hook = root.var:agot_pwl_top
			}
			trigger_else_if = {
				limit = {
					NOT = { exists = var:agot_pwl_top }
					exists = var:agot_pwl_direct
				}
				has_strong_hook = root.var:agot_pwl_direct
			}
			trigger_else = {
				has_strong_hook = root.top_liege
			}
		}
		trigger_else = {
			agot_is_independent_ruler = yes
		}
		top_liege = { agot_is_independent_ruler = yes }
		trigger_if = {
			limit = {
				dynasty ?= { has_dynasty_perk = velaryon_legacy_1 }
			}
			highest_held_title_tier >= tier_duchy
		}
		trigger_else = { highest_held_title_tier >= tier_kingdom }
		any_held_county = {
			is_coastal_county = yes
			any_county_province = { has_holding = yes }
		}
		trigger_if = {
			limit = { is_ai = yes }
			capital_county.title_province = { is_coastal = yes }
		}
	}

	is_valid = {
	}
	owner = founder_primary_title_owner

	province_filter = geographical_region
	province_filter_target = coastal_counties

	is_location_valid = {
		scope:province = {
			scope:founder ?= { has_title = scope:province.county }
			custom_tooltip = {
				text = great_project_type_construct_great_fleet_01_coastal_barony
				is_coastal = yes
				has_holding = yes
			}
			trigger_if = {
				limit = {
					scope:founder ?= { is_ai = yes }
				}
				this = scope:founder.capital_county.title_province
			}
		}
	}

	cost = {
