					limit = {
						is_tributary = yes
						overlord = { has_realm_law_flag = tributaries_more_likely_to_contribute_to_GPs }
					}
					multiply = 2
				}
			}
		}

		laterite_blocks = {
			contributor_is_valid = { highest_held_title_tier > tier_barony }

			cost = {
				gold = mandala_contribution_low_gold_cost
				piety = {
					if = {
						limit = { is_ai = yes }
