		scope:owner = {
			add_prestige = minor_prestige_loss
		}
		every_contribution = {
			limit = {
				contribution_is_funded = yes
			}
			contributor = {
				if = {
					limit = {
						this != scope:owner
						this != scope:founder
					}
					add_to_list = contributors_to_disappoint	
				}
			}
		}
		every_in_list = {
			list = contributors_to_disappoint
